import axiosClient from "@/lib/axios";

export const shipmentsApi = {
  getShipments: (params) => axiosClient.get("/sales-contracts/shipments", { params }),
  getShipment: (id) => axiosClient.get(`/sales-contracts/shipments/${id}`),
  getStats: (params) => axiosClient.get("/sales-contracts/shipments/stats", { params }),
  updateShipment: (id, data) => axiosClient.patch(`/sales-contracts/shipments/${id}`, data),
  updateManualReadiness: (id, data) => axiosClient.patch(`/sales-contracts/shipments/${id}/manual-readiness`, data),
  getExportExcelUrl: (params) => {
    const query = new URLSearchParams(params).toString();
    const baseURL = axiosClient.defaults.baseURL || "";
    return `${baseURL}/sales-contracts/shipments/export/excel?${query}`;
  },
  exportExcel: (params) => 
    axiosClient.get("/sales-contracts/shipments/export/excel", {
      params,
      responseType: "blob",
    }),
  getStuffingExecution: (id) => axiosClient.get(`/sales-contracts/shipments/${id}/stuffing-execution`),
  saveStuffingExecution: (id, data) => axiosClient.post(`/sales-contracts/shipments/${id}/stuffing-execution`, data),
  uploadStuffingAttachment: (id, formData) =>
    axiosClient.post(`/sales-contracts/shipments/${id}/stuffing-execution/attachments`, formData, {
      headers: { "Content-Type": "multipart/form-data" },
    }),
};
